-- ============================================================
-- SEED EXT 4: Módulo 21 — Inversion (ex 146-220)
-- Novos tópicos: inversão em academic writing avançado,
-- inversão com only + adverbial, inversão em TOEFL speaking
-- formal, inversão após so/such + that
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'inversion';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo inversion não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Inversão com only + adverb/prepositional phrase
  (cid,41,146,'gap_fill','Only after the financial crisis _____ policymakers _____ (begin) to understand the systemic risks that had been building.','did / begin',NULL,'"Only after + clause" → inversion: did + subject + base verb.','hard'),
  (cid,41,147,'gap_fill','Only by _____ (invest) heavily in education can a society _____ (hope) to sustain long-term economic _____ (grow).','investing / hope / growth',NULL,'"Only by + gerund" → inversion: can + subject + base verb.','hard'),
  (cid,41,148,'multiple_choice','Which sentence correctly inverts after "Only then"?','Only then did researchers realize the full significance of their discovery.','["Only then researchers realized the full significance of their discovery.","Only then did researchers realize the full significance of their discovery.","Only then realized researchers the full significance of their discovery.","Only then had researchers realize the full significance of their discovery."]','"Only then" → did + subject + base verb. "Realize" (not realized) after did.','medium'),
  (cid,41,149,'gap_fill','Only when all the evidence _____ (present/passive) _____ the committee _____ (feel) confident enough to proceed.','had been presented / did / feel',NULL,'"Only when + PP clause" → did + subject + base verb.','hard'),
  (cid,41,150,'multiple_choice','Which "only" inversion is CORRECTLY formed?','Only rarely does a discovery of this magnitude emerge in a single lifetime of scientific work.','["Only rarely a discovery of this magnitude emerges in a single lifetime.","Only rarely does a discovery of this magnitude emerge in a single lifetime of scientific work.","Only rarely did a discovery of this magnitude emerges in a single lifetime.","Only rarely emerges a discovery of this magnitude in a single lifetime."]','"Only + adverb/phrase" → does/did + subject + base verb.','medium'),

  -- BLOCK 42: Inversão com NOT ONLY...BUT ALSO
  (cid,42,151,'gap_fill','Not only _____ the new treatment more effective than existing alternatives, but it _____ (also/produce) significantly fewer side effects.','is / also produces',NULL,'"Not only" → subject-auxiliary inversion: is + subject. "But it" = no inversion in second clause.','hard'),
  (cid,42,152,'gap_fill','Not only _____ the researchers _____ (identify) a new mechanism, but they _____ (also/develop) a diagnostic test that _____ (enable) early detection.','did / identify / also developed / enables',NULL,'Not only did + subject + base verb... but they (no inversion) + past simple.','hard'),
  (cid,42,153,'multiple_choice','Which "not only...but also" sentence is CORRECTLY inverted?','Not only has the climate changed significantly, but the pace of change has accelerated.','["Not only the climate has changed significantly, but also the pace of change has accelerated.","Not only has the climate changed significantly, but the pace of change has accelerated.","Not only has the climate changed significantly, but also has the pace of change accelerated.","Not only did the climate change significantly, but also did the pace of change accelerate."]','"Not only has" (inversion in first clause). "But (also)" = no inversion in second clause.','hard'),
  (cid,42,154,'gap_fill','Not only _____ the technology _____ (transform) industrial production, but it _____ (also/fundamentally/reshape) labor markets across the developed world.','has / transformed / also fundamentally reshaped',NULL,'Not only has + subject + PP; but it + PS for parallel past transformation.','hard'),

  -- BLOCK 43: Inversão com so...that / such...that
  (cid,43,155,'gap_fill','So _____ (compelling) _____ the evidence that the committee _____ (vote) unanimously to proceed.','compelling / was / voted',NULL,'"So + adj + was/is + subject + that": inverted so-that structure.','hard'),
  (cid,43,156,'gap_fill','Such _____ the scale of the destruction _____ rescue operations _____ (not/be) able to begin for several days.','was / that / were not',NULL,'"Such was + subject + that + result clause" = inversion for emphasis.','hard'),
  (cid,43,157,'multiple_choice','Which inverted "so...that" sentence is correct?','So profound were the implications of the discovery that it triggered a complete reassessment of the theoretical framework.','["So profound the implications of the discovery were that it triggered a reassessment.","So profound were the implications of the discovery that it triggered a complete reassessment of the theoretical framework.","So profound was the implications of the discovery that it triggered a reassessment (subject-verb agreement error: implications = plural).","So profound that the implications of the discovery triggered a complete reassessment."]','"So + adj + were + plural subject + that + result."','hard'),
  (cid,43,158,'gap_fill','So _____ (rapid) _____ the spread of the infection _____ health authorities _____ (not/contain) it before it crossed international borders.','rapid / was / that / could not contain',NULL,'"So rapid was the spread that" = inverted so-that + modal past negative.','hard'),

  -- BLOCK 44: Inversão com negativos (Never / Rarely / Seldom / Little)
  (cid,44,159,'gap_fill','Little _____ the researchers _____ (know) that their discovery _____ (open) an entirely new field of investigation.','did / know / would open',NULL,'"Little did + subject + base verb" = formal inversion of negative adverb.','hard'),
  (cid,44,160,'gap_fill','Rarely _____ a finding so clearly _____ (challenge) the dominant paradigm while simultaneously _____ (offer) a more coherent alternative.','does / challenge / offering',NULL,'"Rarely does + subject + base verb" = inversion of negative frequency adverb.','hard'),
  (cid,44,161,'multiple_choice','Which negative inversion is CORRECT?','Seldom has a single study generated such immediate and widespread controversy.','["Seldom a single study has generated such immediate and widespread controversy.","Seldom has a single study generated such immediate and widespread controversy.","Seldom did a single study has generated such widespread controversy.","Seldom generated a single study such immediate and widespread controversy."]','"Seldom + has + subject + PP" = past perfect/present perfect inversion.','medium'),
  (cid,44,162,'gap_fill','Never before _____ a global health crisis _____ (reveal) so starkly the inequalities in national healthcare systems.','had / revealed',NULL,'"Never before had + subject + PP" = past perfect inversion.','hard'),
  (cid,44,163,'gap_fill','At no point _____ the investigators _____ (find) evidence to support the original hypothesis.','did / find',NULL,'"At no point did + subject + base verb" = inversion with "at no point."','hard'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,164,'multiple_choice','[TOEFL Reading] "Rarely do environmental crises resolve without significant institutional change." This inverted sentence emphasizes:','That institutional change is an unusual but necessary condition for crisis resolution.','["That environmental crises always resolve","That institutional change is an unusual but necessary condition for crisis resolution.","That environmental crises cannot be resolved","That institutional change occurs frequently"]','"Rarely do" = inverted negative adverb, emphasizing the infrequency of resolution without change.','medium'),
  (cid,45,165,'gap_fill','[TOEFL Reading] "Not only _____ the Industrial Revolution transform production methods, but it _____ also fundamentally alter the structure of urban life." Best forms (formal essay context)?','did / did',NULL,'"Not only did + subject + base verb; but it also did + base verb" — OR "but it also + past verb."','hard'),
  (cid,45,166,'multiple_choice','[TOEFL Reading] "So significant were the methodological advances of the 1990s that modern computational linguistics would be unrecognizable to a researcher from 1980." The inverted structure:','Foregrounds the degree of the methodological advances by placing the adjective first.','["Makes the sentence passive","Creates a conditional structure","Foregrounds the degree of the methodological advances by placing the adjective first.","Introduces a non-defining relative clause"]','Inverted so-adj+verb = emphatic focus on the degree of significance.','hard'),
  (cid,45,167,'gap_fill','[TOEFL Reading] "Little _____ the early investors _____ (know) that the company _____ (eventually/become) one of the largest corporations in history." Best forms?','did / know / would eventually become',NULL,'"Little did + subject + know + that + would + base verb" for historical irony.','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,168,'production','[TOEFL Speaking — 45s] A lecture discusses the unexpected consequences of a scientific development. Use inversions (not only/rarely/never/only then) to add rhetorical force to your summary.','',NULL,'The lecture describes the development of the internet and argues that its consequences for social and political life were almost entirely unanticipated. Rarely in the history of technology has an innovation spread as rapidly or reshaped as many aspects of social organization simultaneously. Not only did the internet transform commercial activity, but it also fundamentally altered how political information is produced, distributed, and consumed. Only after the platform companies had grown to a scale of global influence did regulators and governments begin to understand the governance challenges they posed — and by then, the companies were deeply embedded in economic and social infrastructure that made intervention costly and politically difficult. Never before had so much economic and informational power concentrated in so few private hands without triggering the regulatory scrutiny that such concentration would previously have prompted.','hard'),
  (cid,46,169,'production','[TOEFL Speaking — 45s] Discuss the environmental consequences of rapid economic development. Use at least 3 different inversion patterns.','',NULL,'The environmental consequences of rapid economic development have in many cases proven more severe than policymakers anticipated at the time the growth was occurring. Rarely has economic development at pace in the twentieth century left the natural environment in a better condition than it found it. Not only has rapid industrialization depleted many non-renewable resources and produced large quantities of atmospheric pollution, but it has also altered ecosystems that took millennia to develop and that provide services to human welfare that markets consistently fail to price adequately. Only when the costs of environmental degradation became economically visible — through declining agricultural yields, increased flood damage, and health costs from air pollution — did many governments begin to incorporate environmental considerations seriously into economic planning. Never before had humanity been in a position to alter the atmospheric composition of the planet, and never before had the decision-making systems that govern economic activity been less well-suited to managing a challenge that operates on a timescale longer than any electoral cycle.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,170,'production','[TOEFL Writing — 150 words] Write a body paragraph on scientific consensus and public skepticism. Use at least 4 inversion patterns.','',NULL,'Rarely in modern history has the relationship between scientific consensus and public belief been as fraught as it is today. Not only have anti-science movements gained significant political traction, but they have also been amplified by digital platforms whose algorithmic structures reward emotional engagement over factual accuracy. So pervasive has the spread of scientific misinformation become that public health authorities now regard it as a parallel pandemic — an infodemic — requiring active countermeasures. Only when trusted community figures and institutions actively communicated evidence-based guidance during the COVID-19 pandemic did compliance with protective measures tend to be highest. Never before had the scientific community been required to communicate complex, evolving evidence in real time to a global audience, often against a backdrop of coordinated disinformation campaigns. The challenge of maintaining public trust in science in this environment requires not only better science communication but also structural reforms to the informational systems through which citizens receive and evaluate evidence.','hard'),
  (cid,47,171,'production','[TOEFL Writing — Error Correction] Fix inversion errors: "Rarely a scientist makes such a fundamental discovery. Not only the economy grew rapidly but also the inequality worsened. So severe was the crisis the government could not respond adequately. Only after the trial concluded did the truth come out (correct — no fix needed). Little did they knew the consequences."','',NULL,'Rarely a scientist makes → Rarely does a scientist make (does + subject + base verb); Not only the economy grew → Not only did the economy grow (inversion required after not only); but also the inequality worsened → but inequality also worsened OR but also did inequality worsen (second clause can optionally invert); So severe was the crisis the government → So severe was the crisis that the government (''that'' required in so+adj+verb+subject+that); Only after... (correct); did they knew → did they know (base verb after did, not past: knew → know).','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,172,'production','[TOEFL Writing — 200 words] Write a paragraph on the rise of authoritarian politics in the 21st century. Use at least 5 inversion patterns of different types.','',NULL,'Rarely in the post-Cold War period had democratic consolidation seemed as secure as it did in the early 1990s, when the collapse of the Soviet Union appeared to confirm that liberal democracy represented the endpoint of political development. Not only had the major military dictatorships of Latin America given way to elected governments, but former communist states across Central and Eastern Europe were establishing constitutional democracies with impressive speed. So confident were liberal theorists about the direction of political change that Francis Fukuyama declared "the end of history." Only after the first decade of the new millennium did the warning signs of democratic backsliding begin to multiply into a recognizable pattern. Seldom had so many established democracies simultaneously exhibited such similar symptoms: rising executive dominance, the erosion of institutional checks and balances, attacks on independent media and judicial independence, and the mobilization of majoritarian sentiment against minorities. Never before in the democratic era had social media been available to facilitate the kind of direct, emotion-driven communication between populist leaders and their followers that traditional media gatekeepers had previously moderated. The result is a political environment in which democratic norms and institutions face challenges that their designers did not anticipate and their defenders have so far struggled to address.','hard'),
  (cid,48,173,'production','[TOEFL Speaking — 60s] Discuss the history of women''s rights movements. Use at least 4 inversion patterns.','',NULL,'Rarely in political history has a social movement achieved such fundamental transformations in legal status, economic participation, and cultural recognition in a relatively compressed historical period as the women''s rights movement of the nineteenth and twentieth centuries. Not only did first-wave feminism win formal legal equality — the right to vote, to own property, and to stand for election — but second-wave feminism extended the agenda to social and economic equality, reproductive rights, and the recognition of domestic labor as economically significant. So significant were the changes achieved between 1920 and 1970 that the daily lives of women in wealthy countries were almost unrecognizable from what they had been for their grandmothers. Only after the gains of the second wave had been consolidated did a third-wave and subsequently fourth-wave feminism emerge to address questions of intersectionality — recognizing that women''s experiences differ profoundly according to race, class, sexuality, and geography in ways that earlier feminist frameworks had not always adequately acknowledged. Never before had the concept of gender been subject to the kind of theoretical examination that contemporary feminist scholarship provides, raising questions about the social construction of identity that continue to generate significant intellectual and political controversy.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
